package fraymus.workspace;

import org.junit.Test;
import static org.junit.Assert.*;
import org.json.*;
import java.awt.*;
import java.awt.image.BufferedImage;
import javax.imageio.ImageIO;
import java.io.*;
import java.nio.file.*;
import java.util.*;

public class TrackingLabTest {
    static JSONObject pack(String name,String split,int offset,boolean reshape) throws Exception {BufferedImage photo;try(var in=TrackingLabTest.class.getResourceAsStream("/perception/astronaut.png")){photo=ImageIO.read(in);}var frames=new JSONArray();for(int i=0;i<8;i++){int x=25+offset+i*3,y=40,w=96+(reshape?i*5:0),h=96-(reshape?i*4:0);var image=new BufferedImage(320,240,BufferedImage.TYPE_INT_RGB);var g=image.createGraphics();g.setColor(new Color(0x233b50+(offset<<8)));g.fillRect(0,0,320,240);g.drawImage(photo,x,y,w,h,null);g.dispose();var mask=new BufferedImage(320,240,BufferedImage.TYPE_BYTE_INDEXED);for(int py=y;py<y+h;py++)for(int px=x;px<x+w;px++)mask.getRaster().setSample(px,py,0,1);var row=new JSONObject().put("sourceFrame",i).put("imageName",name+"/"+i+".png").put("maskName",name+"/"+i+"-mask.png");for(var part:Map.of("image",image,"mask",mask).entrySet()){var bytes=new ByteArrayOutputStream();ImageIO.write(part.getValue(),"png",bytes);row.put(part.getKey(),Base64.getEncoder().encodeToString(bytes.toByteArray())).put(part.getKey()+"Sha256",PerceptionStore.hash(bytes.toByteArray()));}frames.put(row);}return new JSONObject().put("schema","fraynix-tracking-sequence-v1").put("title",name).put("sequence",name).put("split",split).put("objectId",1).put("source","Local explicitly synthetic motion/aspect fixture with public-domain NASA photograph").put("license","NASA public-domain photograph; generated test composition").put("notes","Synthetic regression only; not real recorded movement").put("frames",frames);}
    static JSONObject importPack(TrackingLab lab,JSONObject pack) throws Exception {var meta=new JSONObject(pack.toString());meta.remove("frames");meta.put("frameCount",pack.getJSONArray("frames").length());String id=lab.begin(meta).getString("id");for(int i=0;i<pack.getJSONArray("frames").length();i++)lab.upload(id,i,pack.getJSONArray("frames").getJSONObject(i));return lab.commit(id);}
    static JSONObject waitFor(TrackingLab lab,String id) throws Exception {for(int i=0;i<2000;i++){var j=lab.read(id);if(!j.getString("status").equals("running"))return j;Thread.sleep(10);}throw new AssertionError("CPU comparison did not settle");}
    @Test public void importedOriginalsAreImmutableIdempotentAndSurviveRestart() throws Exception {var root=Files.createTempDirectory("tracking-import");var p=pack("development","development",0,false);String id;try(var lab=new TrackingLab(root,TrackingEvaluation.CANDIDATE)){var d=importPack(lab,p);id=d.getString("id");assertEquals(id,importPack(lab,p).getString("id"));assertTrue(lab.pack(id).similar(p));var copy=lab.readDataset(id);copy.getJSONArray("frames").getJSONObject(0).put("sourceFrame",999);assertEquals(0,lab.readDataset(id).getJSONArray("frames").getJSONObject(0).getInt("sourceFrame"));}try(var lab=new TrackingLab(root,TrackingEvaluation.CANDIDATE)){assertTrue(lab.pack(id).similar(p));Files.write(root.resolve("tracking-lab/datasets").resolve(id).resolve("0.image"),new byte[]{1,2});assertThrows(IllegalStateException.class,()->lab.pack(id));}}
    @Test public void stagedImportRejectsOrderIncompleteAndHashChanges() throws Exception {try(var lab=new TrackingLab(Files.createTempDirectory("tracking-staging"),TrackingEvaluation.CANDIDATE)){var p=pack("development","development",0,false);var meta=new JSONObject(p.toString());meta.remove("frames");meta.put("frameCount",8);var id=lab.begin(meta).getString("id");assertThrows(IllegalStateException.class,()->lab.commit(id));assertThrows(IllegalStateException.class,()->lab.upload(id,1,p.getJSONArray("frames").getJSONObject(0)));var f=p.getJSONArray("frames").getJSONObject(0);lab.upload(id,0,f);lab.upload(id,0,f);var altered=new JSONObject(f.toString()).put("imageSha256","f".repeat(64));assertThrows(IllegalStateException.class,()->lab.upload(id,0,altered));assertThrows(IllegalArgumentException.class,()->lab.upload(id,1,altered));lab.cancelImport(id);assertThrows(IllegalStateException.class,()->lab.commit(id));}}
    @Test public void declaredSplitsCannotShareExactFrames() throws Exception {try(var lab=new TrackingLab(Files.createTempDirectory("tracking-split"),TrackingEvaluation.CANDIDATE)){var p=pack("development","development",0,false);var d=importPack(lab,p);var q=new JSONObject(p.toString()).put("sequence","different-name").put("split","evaluation");var e=importPack(lab,q);assertThrows(IllegalArgumentException.class,()->lab.start(new JSONArray().put(d.getString("id")).put(e.getString("id")),true));assertFalse(lab.busy());}}
    @Test public void actualComparisonRetainsFailuresAndCannotPromoteAnUnpassedJob() throws Exception {var root=Files.createTempDirectory("tracking-comparison");try(var lab=new TrackingLab(root,TrackingEvaluation.CANDIDATE)){var d=importPack(lab,pack("development","development",0,false));var e=importPack(lab,pack("evaluation","evaluation",15,false));var j=waitFor(lab,lab.start(new JSONArray().put(d.getString("id")).put(e.getString("id")),true).getString("id"));assertEquals(j.toString(2),"completed",j.getString("status"));assertEquals(2,j.getJSONArray("results").length());assertEquals(7,j.getJSONObject("gate").getInt("scoredEvaluationFrames"));assertFalse("No demonstrated gain on this unchanged-aspect control",j.getJSONObject("gate").getBoolean("passed"));{assertEquals(TrackingEvaluation.BASELINE,lab.activeProfile());assertThrows(IllegalStateException.class,()->lab.promote(j.getString("id")));}lab.rollback();assertEquals(TrackingEvaluation.BASELINE,lab.activeProfile());}try(var lab=new TrackingLab(root,TrackingEvaluation.CANDIDATE)){assertEquals(1,lab.state().getJSONArray("jobs").length());assertEquals(TrackingEvaluation.BASELINE,lab.activeProfile());}}
    @Test public void stoppedComparisonNeverActivatesAPartialResult() throws Exception {var root=Files.createTempDirectory("tracking-stop");try(var lab=new TrackingLab(root,TrackingEvaluation.CANDIDATE)){var d=importPack(lab,pack("development","development",0,false));var e=importPack(lab,pack("evaluation","evaluation",15,true));var j=lab.start(new JSONArray().put(d.getString("id")).put(e.getString("id")),true);lab.cancel(j.getString("id"));assertEquals("cancelled",lab.read(j.getString("id")).getString("status"));assertThrows(IllegalArgumentException.class,()->lab.promote(j.getString("id")));assertEquals(TrackingEvaluation.BASELINE,lab.activeProfile());}}
    @Test public void passingAspectChangeActivatesThenRollsBackAcrossRestart() throws Exception {var root=Files.createTempDirectory("tracking-activation");String job;try(var lab=new TrackingLab(root,TrackingEvaluation.CANDIDATE)){var d=importPack(lab,pack("development","development",0,false));var e=importPack(lab,pack("aspect-evaluation","evaluation",15,true));var j=waitFor(lab,lab.start(new JSONArray().put(d.getString("id")).put(e.getString("id")),true).getString("id"));job=j.getString("id");assertEquals(j.toString(2),"completed",j.getString("status"));assertTrue(j.getJSONObject("gate").toString(2),j.getJSONObject("gate").getBoolean("passed"));assertEquals(TrackingEvaluation.CANDIDATE,lab.activeProfile());}try(var lab=new TrackingLab(root,TrackingEvaluation.CANDIDATE)){assertEquals(TrackingEvaluation.CANDIDATE,lab.activeProfile());assertEquals(job,lab.state().getString("activeJob"));lab.rollback();assertEquals(TrackingEvaluation.BASELINE,lab.activeProfile());}try(var lab=new TrackingLab(root,TrackingEvaluation.CANDIDATE)){assertEquals(TrackingEvaluation.BASELINE,lab.activeProfile());assertEquals("rollback",lab.state().getJSONArray("history").getJSONObject(1).getString("event"));}}
    @Test public void goalsRejectAChangedPinnedImplementationBeforeStarting() throws Exception {var root=Files.createTempDirectory("tracking-code-pin");try(var artifacts=new WorkspaceStore(root);var scenes=new SceneStore(root);var brain=new BrainService(root);var spatial=new SpatialStore(root);var perception=new PerceptionStore(root);var goals=new GoalRunner(root,scenes,brain,artifacts,new MeasurementStore(root),spatial,perception)){var frame=perception.frame(PerceptionTest.packet(PerceptionTest.scene(35,30,1,false),UUID.randomUUID().toString(),"1",1000));assertThrows(IllegalStateException.class,()->goals.startPerception(new JSONObject().put("frameId",frame.getString("id")).put("mode","dom").put("trackerProfile",TrackingEvaluation.CANDIDATE).put("trackerCodeSha256","f".repeat(64))));assertEquals(0,goals.list().length());assertFalse(perception.busy());}}
    @Test public void implementationPinsIncludeFeatureExtractionAndGeometryHelpers() throws Exception {var c=TrackerIdentity.components(TrackingEvaluation.CANDIDATE);assertTrue(c.has("AdaptiveTracker$Plane"));assertTrue(c.has("PixelTracker$Box"));assertTrue(c.has("TrackingEvaluation"));assertNotEquals(TrackerIdentity.hash(TrackingEvaluation.BASELINE),TrackerIdentity.hash(TrackingEvaluation.CANDIDATE));assertEquals(TrackerIdentity.hash(TrackingEvaluation.CANDIDATE),TrackerIdentity.hash(TrackingEvaluation.CANDIDATE));}
}
